3	const WORKSPACE_STORAGE_KEY = 'mlflow.activeWorkspace';
4	export const WORKSPACE_QUERY_PARAM = 'workspace';
5	
6	let activeWorkspace: string | null = null;
7	
8	export const getActiveWorkspace = () => activeWorkspace;
9	
10	export const setActiveWorkspace = (workspace: string | null) => {
11	  activeWorkspace = workspace;
12	  if (workspace) {
13	    setLastUsedWorkspace(workspace);
14	  }
15	};
16	
17	/**
18	 * Get the last used workspace from localStorage.
19	 * Used for UI hints like the "Last used" badge.
20	 */
21	export const getLastUsedWorkspace = (): string | null => {
22	  if (typeof window === 'undefined') {
23	    return null;
24	  }
25	  try {
26	    return window.localStorage.getItem(WORKSPACE_STORAGE_KEY);
27	  } catch {
28	    return null;
29	  }
30	};
31	
32	/**
33	 * Set the active workspace in localStorage and notify listeners.
34	 * Used for syncing state with URL and for UI hints via getLastUsedWorkspace().
35	 */
36	export const setLastUsedWorkspace = (workspace: string | null) => {
37	  if (typeof window !== 'undefined') {
38	    try {
39	      if (workspace) {
40	        window.localStorage.setItem(WORKSPACE_STORAGE_KEY, workspace);
41	      } else {
42	        window.localStorage.removeItem(WORKSPACE_STORAGE_KEY);
43	      }
44	    } catch {
45	      // no-op: localStorage might be unavailable (e.g., private browsing)
46	    }
47	  }
48	};
