74	                  ? `linear-gradient(163deg, rgba(66, 153, 224, 0.06) 20%, rgba(202, 66, 224, 0.06) 35%, rgba(255, 95, 70, 0.06) 50%, transparent 80%), ${theme.colors.backgroundSecondary}`
75	                  : theme.colors.backgroundSecondary,
76	            }}
77	          >
78	            <MlflowSidebar showSidebar={showSidebar} setShowSidebar={setShowSidebar} />
79	            <main
80	              css={{
81	                width: '100%',
82	                backgroundColor: theme.colors.backgroundPrimary,
83	                margin: theme.spacing.sm,
84	                borderRadius: theme.borders.borderRadiusMd,
85	                boxShadow: theme.shadows.md,
86	                overflowX: 'auto',
87	              }}
88	            >
89	              <React.Suspense fallback={<LegacySkeleton />}>
90	                <Outlet />
91	              </React.Suspense>
92	            </main>
