100	/**
101	 * This is root element for MLflow routes, containing app header.
102	 */
103	const MlflowRootRoute = () => {
104	  useInitializeExperimentRunColors();
105	
106	  const routeTitle = usePageTitle();
107	  useDocumentTitle({ title: routeTitle });
108	
109	  const [showSidebar, setShowSidebar] = useState(true);
110	  const { experimentId } = useParams();
111	  const enableWorkflowBasedNavigation = shouldEnableWorkflowBasedNavigation();
112	
113	  // Hide sidebar if we are in a single experiment page (only when feature flag is disabled)
114	  const isSingleExperimentPage = Boolean(experimentId);
115	  useEffect(() => {
116	    // When feature flag is enabled, sidebar should always retain its current state
117	    if (enableWorkflowBasedNavigation) {
118	      return;
119	    }
120	    setShowSidebar(enableWorkflowBasedNavigation || !isSingleExperimentPage);
121	  }, [isSingleExperimentPage, enableWorkflowBasedNavigation]);
122	
123	  return (
124	    <AssistantProvider>
125	      <AssistantRouteContextProvider />
126	      <WorkflowTypeProvider>
127	        <MlflowRootLayout showSidebar={showSidebar} setShowSidebar={setShowSidebar} />
128	      </WorkflowTypeProvider>
129	    </AssistantProvider>
130	  );
131	};
