133	const WorkspaceRouterSync = ({ workspacesEnabled }: { workspacesEnabled: boolean }) => {
134	  const location = useLocation();
135	  const [searchParams] = useSearchParams();
136	  const navigate = useNavigate({ bypassWorkspacePrefix: true });
137	  const { workspaces, isLoading } = useWorkspaces(workspacesEnabled);
138	
139	  useEffect(() => {
140	    if (!workspacesEnabled) {
141	      setActiveWorkspace(null);
142	      // Clear localStorage so stale workspace values don't leak into
143	      // requests (e.g. X-MLFLOW-WORKSPACE header) when the server
144	      // no longer supports workspaces.
145	      setLastUsedWorkspace(null);
146	      return;
147	    }
148	
149	    // Extract workspace from query param
150	    const workspaceFromQuery = extractWorkspaceFromSearchParams(searchParams);
151	    const activeWorkspace = getActiveWorkspace();
152	    const isRootPath = location.pathname === '/' || location.pathname === '';
153	
154	    // If workspace is in query param, validate it once workspaces are loaded
155	    if (workspaceFromQuery) {
156	      if (isLoading) {
157	        // Still loading workspaces, optimistically set the workspace
158	        // (will validate once loaded)
159	        if (activeWorkspace !== workspaceFromQuery) {
160	          setActiveWorkspace(workspaceFromQuery);
161	        }
162	        return;
163	      }
164	
165	      // Workspaces loaded - validate
166	      const workspaceExists = workspaces.some((ws) => ws.name === workspaceFromQuery);
167	      if (!workspaceExists) {
168	        // Invalid workspace - clear it and redirect to workspace selector
169	        setActiveWorkspace(null);
170	        navigate('/', { replace: true });
171	        return;
172	      }
173	
174	      // Valid workspace - sync to active state
175	      if (activeWorkspace !== workspaceFromQuery) {
176	        setActiveWorkspace(workspaceFromQuery);
177	      }
178	      return;
179	    }
180	
181	    // No workspace query param - check if this is a global route
182	    const isOnGlobalRoute = isRootPath || isGlobalRoute(location.pathname);
183	
184	    if (isOnGlobalRoute) {
185	      // Clear active workspace on global routes (workspace selector, settings)
186	      if (activeWorkspace) {
187	        setActiveWorkspace(null);
188	      }
189	      return;
190	    }
191	
192	    // No workspace query param or local storage on a workspace-scoped route - redirect to selector
193	    const lastUsedWorkspace = getLastUsedWorkspace();
194	    if (!lastUsedWorkspace) {
195	      setActiveWorkspace(null);
196	      navigate('/', { replace: true });
197	      return;
198	    } else {
199	      navigate(location.pathname + '?workspace=' + lastUsedWorkspace, { replace: true });
200	    }
201	  }, [location, navigate, workspacesEnabled, searchParams, workspaces, isLoading]);
202	
203	  return null;
204	};
