const detectWorkspaceNotFound = (error: unknown): string | null => {
  if (!error) {
    return null;
  }

  let isResourceNotFound = false;
  let message = '';
  if (error instanceof ErrorWrapper) {
    isResourceNotFound = error.getErrorCode() === ErrorCodes.RESOURCE_DOES_NOT_EXIST || Number(error.getStatus()) === 404;
