    message = typeof messageField === 'string' && messageField !== ErrorCodes.INTERNAL_ERROR ? messageField : '';
  } else if (error instanceof Error) {
    isResourceNotFound =
      error.name === 'NotFoundError' || (error as { errorCode?: string }).errorCode === ErrorCodes.RESOURCE_DOES_NOT_EXIST;
