  }

  if (!isResourceNotFound) {
    return null;
  }

  // Require the message to reference a workspace to avoid matching unrelated
  // not-found errors such as "Experiment not found".
  if (!/workspace/i.test(message) || !/not\s+found/i.test(message)) {
